// ── What you typed while the answer was still coming ───────
//
// Two lists, because there are two fates. A turn is a round of requests, and
// between any two of them the agent rebuilds the message list -- so a correction
// typed into the chat on screen goes to the RUNNING agent (`_interject`) and is
// said at that seam, in the turn it was meant to redirect. Nothing can be added
// to a request already in flight, and a turn spending its whole length writing
// prose has no seam in it at all; whatever is still waiting when the turn ends
// comes back and joins the QUEUE (`_queue`), which sends it as its own turn.
//
// The queue is also where a message typed at a chat in the background goes:
// runTurn draws into the live thread, so a turn started for a conversation the
// user has left would write itself into the one they are looking at.
//
// One turn per queued message, never coalesced: a turn is the unit a fold picks
// and the unit the numbering counts, so two questions merged into one turn would
// be two things that could never be folded apart again.
//
// Both lists live on the chat and are deliberately NOT persisted: they are a
// half-second of intent, not content, and either restored after a crash would
// spend money on a turn the user cannot remember asking for.

/// Hold a message until the turn in flight has finished. `words`, where the box held
/// something other than `text` (a `/concise` prefix is added on the way), is what the
/// composer gives up for it.
/// The words of queued item `q`.
function queuedText(q) { return String((q && q.text) || ''); }

/// Keep on disk every word of `chat`'s that the box has given up and the stored conversation
/// does not yet hold, so a reload hands it back to the composer (`giveBackQueue`) rather than
/// losing it (D-20261012-07). Two records, by whose they are:
/// - what a turn running HERE took at a seam (`_jsaid`) and what was said into it, in that
///   turn's journal entry, only while it runs (after it closes its entry is gone);
/// - the chat's QUEUE, the item a drain has taken and not yet turned into a prompt row
///   (`_qflight`) first, in the chat's own record on every change, whether or not a turn runs
///   here (QA ccp3 A R2): behind a hand-off nothing runs here, and the queue was then only in
///   tab memory.
export function journalQueue(chat) {
	if (!chat || !chat.id || !window.DaimondJournal) return;
	if (chat._jturn && chat._generating) {
		var said = (chat._jsaid || []).concat(chat._interject || []);
		var sig = chat._jturn + '\n' + JSON.stringify(said);
		if (sig !== chat._jqSig) {
			chat._jqSig = sig;
			try { DaimondJournal.queueSet(chat._jturn, chat.id, said); } catch (e) { /* no IDB: they live as long as the tab */ }
		}
	}
	var q = JSON.stringify((chat._qflight ? [chat._qflight] : []).concat(chat._queue || []).map(queuedText));
	if (q === (chat._jqKept || '[]')) return;
	chat._jqKept = q;
	try { DaimondJournal.chatQueue(chat.id, JSON.parse(q)); } catch (e) { /* no IDB: the queue lives as long as the tab */ }
}

/// A journalled turn begins: what waits on it is written under its id from here on.
export function journalTurnBegins(chat, turnId) {
	chat._jturn = String(turnId || '');
	chat._jsaid = [];
	chat._jqSig = '';
	journalQueue(chat);
}

/// Hand words a reload cut off back to `chat`'s composer, unsent (D-20261012-07): into
/// the box when that chat is on screen, else into its kept draft, ahead of anything
/// already there. Once per turn in this tab, however often recovery runs.
var _queueGiven = {};
export function giveBackQueue(chat, turnId, items) {
	if (!chat || !items || !items.length || _queueGiven[turnId]) return;
	_queueGiven[turnId] = true;
	intoComposer(chat, items.join('\n\n'), true);
	toast(t('chat.queue_returned'), true);
}

/// Hand back the queues a tab now gone left on disk (`DaimondJournal.chatQueue`, QA ccp3 A R2):
/// into each chat's composer, unsent, as a turn's are (D-20261012-07). A reload is no press,
/// so the runner each was pressed under goes with it and he sends them again. Cleared once
/// given back (the draft holds them by then); a chat that is gone takes its queue with it.
export function giveBackQueues(queues) {
	(queues || []).forEach(function (q) {
		var chat = null;
		for (var i = 0; i < pg.chats.length; i++) if (pg.chats[i] && pg.chats[i].id === q.chatId) { chat = pg.chats[i]; break; }
		if (chat) giveBackQueue(chat, q.stream, (q.items || []).map(String));
		try { DaimondJournal.clearQueue(q.stream); } catch (e) { /* the next boot clears it */ }
	});
}

///
/// A queued item is `{ text, drawn }`: `drawn` is the runner the switch drew at the press it
/// came from, so the drain elects it under that runner (rulings, last line: gone at drain, it
/// ends "not run" with Retry, never Here). Undefined for words no press sent, which follow the
/// switch at drain (l.19).
export function enqueueMessage(chat, text, words, drawn) {
	chat._queue = chat._queue || [];
	chat._queue.push({ text: text, drawn: drawn });
	diag('queue held', 'chat=' + String(chat.id || '') + ' queued=' + chat._queue.length);
	journalQueue(chat);
	giveUpSent(chat, words === undefined ? text : words);
	syncSendMode();
	renderQueue();
}

/// Say a message into the turn already running, to be delivered at its next seam.
///
/// Hands it to the agent, which is the only thing that knows when a seam comes
/// round; the copy kept here is a mirror to draw from, and the agent's queue is
/// the truth. Returns false when this build's agent cannot take one — an older
/// wasm bundle, or a chat whose agent has been thrown away — so the caller falls
/// back to the queue rather than dropping what was typed.
export function interjectMessage(chat, text, words, from) {
	var into = interjectInto(chat, from);
	if (!into) { diag('said not', 'chat=' + String(chat.id || '') + ' no turn here to hear it'); return false; }
	// A person's message, so it takes the note of what has been rated since the model last heard, composed
	// now and sent with the words. A correction already waiting has told what it told, so this one starts
	// where that one was typed. The same string goes on the record when it lands (`landInterjection`).
	// Words said on ANOTHER device (`from`, the lease's `{ id, pre }`) bring that device's note and id.
	if (!from) commitRatings(chat.id, { });
	var notes = chat._interjectNote || [];
	var pre = from ? String(from.pre || '') : ratingPre(chat, notes.length ? notes[notes.length - 1].at : undefined);
	var at = (chat.messages || []).length;
	// THE ROW ID IS CHOSEN HERE (CCP3 F3), so the engine's message and the row drawn when it
	// lands (`landInterjection`) are one, and two equal corrections stay two in his words log.
	var mid = from ? String(from.id || '') : '';
	if (!mid) mid = newMid();
	try { into(text, pre || undefined, mid); }
	catch (e) { diag('said not', 'chat=' + String(chat.id || '') + ' the turn refused it: ' + ((e && e.message) || e)); return false; }
	diag('said into', 'chat=' + String(chat.id || '') + (from ? ' from another device' : '') + ' at=' + at);
	chat._interject = chat._interject || [];
	chat._interject.push(text);
	notes.push({ pre: pre, at: at, mid: mid });
	chat._interjectNote = notes;
	journalQueue(chat);
	if (!from) giveUpSent(chat, words === undefined ? text : words);
	syncSendMode();
	if (pg.current === chat) renderQueue();
	return true;
}

/// What carries words into the turn `chat` is running HERE, or null where none runs.
///
/// A DIAMOND'S TURN IS SPOKEN TO TOO (UNBLOCK-27 R7). It runs on an agent `steer_crystal`
/// composes for the turn, which shares the Diamond's queue on the app it runs on
/// (`interject_daimon`), so mid-turn words reach it at its next seam as a chat's do.
///
/// A TURN RUN HERE FOR ANOTHER DEVICE HEARS ONLY THAT DEVICE (r578). Its end hands back what
/// it never heard to the device that asked (`reclaimInterjections`, `keep` false), so a word
/// typed here would be dropped by both. Only words relayed over its lease (`from`) go in; a
/// word typed here queues behind the turn and goes out through the election.
function interjectInto(chat, from) {
	if (!chat) return null;
	if (chat.diamondId) {
		var did = String(chat.diamondId), fa = _steerApp[did];
		if (!fa || typeof fa.interject_daimon !== 'function') return null;
		if (_steerDetached[did] && !from) return null;
		return function (text, pre, mid) { fa.interject_daimon(did, text, pre, mid); };
	}
	if (!chat.app || typeof chat.app.interject !== 'function') return null;
	return function (text, pre, mid) { chat.app.interject(text, pre, mid); };
}

/// Say words typed at `chat` into the turn running HERE, but only where the switch keeps its
/// turns here (UNBLOCK-1 QFOLLOW). The one rule for a chat's send and a Diamond's: with the
/// switch on a runner, false, so the caller queues and the queue sends through the election.
export function sayIntoHere(chat, text, words) {
	if (seatNamesRunner(chat)) {
		diag('said not', 'chat=' + String(chat.id || '') + ' switch names a runner: queued for the election');
		return false;
	}
	return interjectMessage(chat, text, words);
}

/// Where words sent to Diamond chat `target` go while a turn of it may be running: said into
/// the turn running here, said to the runner of one handed off, queued behind one that cannot
/// hear them here, or handed off as the next turn. False: none of these, so it steers here.
export async function sendToDiamondTurn(target, text, words, drawn) {
	if (diamondBusy(target.diamondId) && !recoveringHere(target) && sayIntoHere(target, text, words)) return true;
	var heldThere = diamondBusy(target.diamondId) ? null : peerHeldTurnOf(target);
	if (heldThere && await sayToRunner(target, heldThere, text, words)) return true;
	if (diamondBusy(target.diamondId) || recoveringHere(target)) { enqueueMessage(target, text, words, drawn); return true; }
	// Behind a queue already waiting, as a chat's send (QA ccp2 M1).
	if ((target._queue || []).length && !askHolds()) {
		enqueueMessage(target, text, words, drawn);
		drainAfterHeld(target);
		return true;
	}
	return !!(await maybeAutoDispatch(target, text, words, undefined, undefined, drawn));
}

/// Say words into a turn ANOTHER device runs for `chat` (`ph`, its held placeholder), over the
/// turn's lease, where its runner hears them at its next seam (UNBLOCK-27 R7). They join the
/// thread here, where they were sent, under the id the runner records them by, so the two
/// copies are one message. False where nothing is running there to hear them: the caller queues.
async function sayToRunner(chat, ph, text, words) {
	var tid = String((ph && ph.iturn) || '');
	if (!tid || _peerStopping[tid] || !window.DaimondLease || !DaimondLease.say || !window.DaimondPeer) return false;
	// ITS RUNNER RUNS THE SET, OR IT IS NOT SPOKEN TO (D-20261018-09 OR). A turn an older asker
	// handed to a runner before the Models menu is not added to: the words go as the next
	// turn, which the election seats only where the set is honoured.
	var holder = '';
	try { holder = String((DaimondLease.holder && DaimondLease.holder(tid)) || ''); } catch (e) { holder = ''; }
	if (!honoursModelSet(holder)) {
		diag('said not', 'turn=' + tid + ' runner ' + (holder ? holder.slice(0, 8) : 'unknown')
			+ ' has not shown it runs the model set');
		return false;
	}
	// A SAY IS ONLY FOR A TURN THAT CAN STILL HEAR IT (UNBLOCK-27 R7c). Its runner's frames
	// show its answer being written (or the turn over): no seam follows, so the words go out
	// as the next turn now, as they did before turns could be spoken to, and never wait out
	// the answer's tail for a report that names them unheard.
	if (DaimondPeer.frameHears && !DaimondPeer.frameHears(_progressView[tid])) {
		diag('said not', 'turn=' + tid + ' past its last round: sent as the next turn');
		return false;
	}
	commitRatings(chat.id, { });
	var pre = ratingPre(chat);
	var mid = newMid();
	var res;
	try {
		res = await DaimondLease.say(tid, { id: mid, text: text, pre: pre || '' }, DaimondPeer.syncCas(peerSyncShim()));
	} catch (e) { res = { ok: false, why: 'threw' }; }
	diag('said to runner', 'turn=' + tid + ' ok=' + (res && res.ok ? 1 : 0) + ' why=' + String((res && res.why) || ''));
	if (!res || !res.ok) return false;
	(_saidThere[tid] = _saidThere[tid] || []).push({ chatId: String(chat.id || ''), mid: mid, text: text });
	giveUpSent(chat, words === undefined ? text : words);
	pushUserRecord(chat, { role: 'user', interject: true, content: text, mid: mid, ts: Date.now() }, true, pre || '');
	if (pg.current === chat) appendInterjected(text);
	syncSendMode();
	return true;
}

/// The runner has reported on a turn this device said words into (`sayToRunner`): any its report
/// does not name as heard reached the thread here but never the model, said between the runner's
/// last read of the lease and the turn's end. Each goes out once, as the next turn
/// (`resendUnheard`). Answers how many.
export function requeueUnheard(report) {
	var tid = String((report && report.turnId) || '');
	var said = tid ? _saidThere[tid] : null;
	if (!said) return 0;
	delete _saidThere[tid];		// once: a second report of the turn finds nothing
	var heard = Array.isArray(report.heard) ? report.heard.map(String) : [];
	var n = 0;
	said.forEach(function (s) {
		if (heard.indexOf(s.mid) !== -1) return;
		n++;
		resendUnheard(s);
	});
	if (n) diag('said unheard', 'turn=' + tid + ' resent=' + n);
	return n;
}

/// The runner's receipts on the lease view (`DaimondLease.unheard`): words said into a turn that
/// could no longer hear them, answered the moment the runner read them rather than at the turn's
/// end. Each goes out once, as the next turn (`resendUnheard`). Answers how many.
export function heedUnheard() {
	var n = 0;
	if (!window.DaimondLease || !DaimondLease.record) return 0;
	Object.keys(_saidThere).forEach(function (tid) {
		var r = DaimondLease.record(tid);
		var ids = (r && Array.isArray(r.unheard)) ? r.unheard.map(String) : [];
		if (!ids.length) return;
		var left = [], out = [];
		_saidThere[tid].forEach(function (s) { (ids.indexOf(s.mid) !== -1 ? out : left).push(s); });
		if (!out.length) return;
		if (left.length) _saidThere[tid] = left; else delete _saidThere[tid];
		diag('said unheard', 'turn=' + tid + ' receipt=' + out.length);
		out.forEach(function (s) { n++; resendUnheard(s); });
	});
	return n;
}

/// Words said into a handed-off turn that never reached its model go out as the next turn, now,
/// UNDER THE ID THEY WERE SAID AS (UNBLOCK-27 R7c): the turn's message is the said copy restamped,
/// so a device that already holds the said copy holds one row, not that and the turn's message.
/// Where the turn cannot be handed off now, the said copy leaves every thread and the words queue.
async function resendUnheard(s) {
	var chat = pg.chats.find(function (x) { return x && String(x.id) === s.chatId; });
	if (!chat) return false;		// deleted since: nowhere to send it
	var sent = false;
	try { sent = await maybeAutoDispatch(chat, s.text, '', s.mid); }
	catch (e) { sent = false; }
	var ms = chat.messages || [], newest = null;
	for (var i = ms.length - 1; i >= 0; i--) { if (ms[i] && ms[i].mid === s.mid) { newest = ms[i]; break; } }
	if (sent) {
		// The turn's copy is the newest of that id; the said copy it replaces goes.
		var one = ms.filter(function (m) { return !(m && m.mid === s.mid && m !== newest); });
		if (one.length !== ms.length) {
			chat.messages = one;
			try { persistChats(); } catch (e) { /* the dispatch persisted the turn */ }
			if (ownsChat(chat)) renderHistory(chat.messages);
		}
		return true;
	}
	var kept = ms.filter(function (m) { return !(m && m.mid === s.mid); });
	if (kept.length !== ms.length) {
		chat.messages = kept;
		msgTombstone([s.mid]);
		touchChat(chat);
	}
	chat._queue = (chat._queue || []).concat([{ text: s.text }]);
	journalQueue(chat);
	try { persistChats(); } catch (e) { /* the queue is journalled */ }
	if (ownsChat(chat)) renderHistory(chat.messages);
	if (pg.current === chat) renderQueue();
	updateQueueBadges();
	drainAfterHeld(chat);
	return false;
}

/// Send what waits on `chat` once nothing runs it, here or on a runner: the words a handed-off
/// turn ended without hearing, sent at its report or when its answer lands (UNBLOCK-27 R7).
export function drainAfterHeld(chat) {
	if (!chat || !(chat._queue || []).length || chat._generating || recoveringHere(chat)) return;
	if (chat.diamondId ? diamondBusy(chat.diamondId) : false) return;
	var held = dispatchInFlight(chat);
	if (held) {
		// Its answer has not landed: the drop sends it, and if the runner never reports, the
		// hold's own end does (QA ccp2 M1). A lapse being read at the door asks again at the read's end.
		if (_lapseReading[String(chat.id || '')]) return;
		try { armHeldWake(chat, held); } catch (e) { /* a lease change or a merge asks again */ }
		return;
	}
	try { if (chat.diamondId) drainSteerQueue(chat, chat.diamondId, false); else drainQueue(chat, false); }
	catch (e) { /* the queue stays, badged */ }
}

/// The newest hand-off of `c` whose end is read off this device's clock alone: an unanswered
/// placeholder with no report from its runner and no end begun here, whose state is `failed` or
/// `no-peer-awake` only because the lease view this device holds has lapsed. Null when none.
export function lapsedByClock(c) {
	var ms = (c && c.messages) || [];
	for (var i = ms.length - 1; i >= 0; i--) {
		var m = ms[i];
		if (!m || m.why !== 'dispatched' || !m.iturn || (m.content && m.content.trim())) continue;
		var tid = String(m.iturn);
		if (peerReports[tid] || _localEnding[tid] || _localRecovering[tid]) return null;
		var ui = '';
		try { ui = peerUiStateFor(m); } catch (e) { return null; }
		return (ui === 'failed' || ui === 'no-peer-awake') ? m : null;
	}
	return null;
}

/// Read the lease door before `chat`'s queue goes on a lapse seen only by the clock (`lapsedByClock`
/// gave `m`). Read, the fresh view is adopted, the lapse as it then stands is marked confirmed
/// (`lapseConfirmed`) and the queue asked again; unread, the queue waits for the hold's next end.
/// One read per chat at a time: the adopt's own change re-enters `drainAfterHeld` while it is in
/// flight, and finds it here.
var _lapseReading = {};
export function confirmLapse(chat, m) {
	var cid = String((chat && chat.id) || '');
	if (!cid || _lapseReading[cid]) return;
	_lapseReading[cid] = 1;
	leaseDoorRead().then(function (read) {
		delete _lapseReading[cid];
		if (read) { _lapseRead[cid] = lapseMark(m); drainAfterHeld(chat); }
		else { try { armHeldWake(chat, m); } catch (e) { /* a lease change or a merge asks again */ } }
	});
}

/// Per chat id, the lapse last confirmed at the door (`lapseMark`), one per chat, overwritten by
/// the next. A renewal since changes the lease record, so a later lapse of it is read again.
var _lapseRead = {};
function lapseMark(m) {
	var tid = String((m && m.iturn) || '');
	var r = null;
	try { r = (window.DaimondLease && DaimondLease.record) ? DaimondLease.record(tid) : null; } catch (e) { r = null; }
	return tid + '|' + (r ? String(r.holder || '') + '|' + String(r.mode || '') + '|' + String(r.expiry || '') : '');
}

/// Has the door been read since `c`'s lapse `m` (`lapsedByClock`), so the lapse is the lease as it stands?
export function lapseConfirmed(c, m) {
	var cid = String((c && c.id) || '');
	return !!cid && _lapseRead[cid] === lapseMark(m);
}

/// Read the lease at its own door (`DaimondSync.leaseGet`) and adopt it. False when the door
/// cannot be read (unread or offline: unknown, never vacant, so nothing is adopted); true when
/// it was read, or when there is no door, so the view this device holds is all there is.
export async function leaseDoorRead() {
	var S = window.DaimondSync, L = window.DaimondLease;
	if (!(S && S.leaseGet && L && L.adopt)) return true;
	try {
		var door = await S.leaseGet();
		if (!door || door.unread) return false;
		L.adopt(door.leases);
		return true;
	} catch (e) { return false; }
}

/// Ask `chat`'s queue again when the hold `held` (a hand-off still out) must have ended by time
/// alone: the errand's deadline, or the lease's expiry, whichever comes first, so a runner that
/// never reports cannot keep the queue waiting for ever (QA ccp2 M1; rulings l.17). One timer
/// per chat; with neither known, it asks again in a few seconds.
var _heldWake = {};
function armHeldWake(chat, held) {
	var cid = String((chat && chat.id) || '');
	if (!cid) return;
	var now = Date.now(), wait = 0;
	var by = function (ms) { if (ms > 0 && (!wait || ms < wait)) wait = ms; };
	try { if (window.DaimondPeer && window.DaimondPeer.handoffDeadline) by(window.DaimondPeer.handoffDeadline(held) - now); }
	catch (e) { /* no deadline: the lease or the recheck */ }
	try {
		var tid = String((held && held.iturn) || '');
		var rec = tid && window.DaimondLease && window.DaimondLease.record ? window.DaimondLease.record(tid) : null;
		if (rec && rec.expiry) by(Number(rec.expiry) - leaseClockNow());
	} catch (e) { /* no lease: the deadline or the recheck */ }
	wait = wait ? wait + 250 : 5000;
	if (_heldWake[cid]) clearTimeout(_heldWake[cid]);
	_heldWake[cid] = setTimeout(function () {
		delete _heldWake[cid];
		diag('queue wake', 'chat=' + cid + ' the hold must have ended by now: asking the queue again');
		drainAfterHeld(chat);
	}, wait);
}

/// Ask every chat's queue again: the hold may have changed (a lease moved, a merge landed).
export function drainHeldQueues() {
	(pg.chats || []).forEach(function (c) {
		if (c && (c._queue || []).length) { try { drainAfterHeld(c); } catch (e) { /* the next change asks again */ } }
	});
}

/// A correction has landed at the engine's seam: it stops waiting and joins the thread, as a person's
/// message carrying the note it was SENT with, kept with the waiting text, so the record says what the
/// model read and no more. Words typed twice land first in, first out.
export function landInterjection(chat, said) {
	var told = '', mid = '';
	if (chat._interject && chat._interject.length) {
		var at = chat._interject.indexOf(said);
		at = at === -1 ? 0 : at;
		chat._interject.splice(at, 1);
		var kept = (chat._interjectNote || []).splice(at, 1)[0];
		if (kept && typeof kept.pre === 'string') told = kept.pre;
		if (kept && kept.mid) mid = String(kept.mid);
	}
	// Said on another device under an id the thread already holds (UNBLOCK-27 R7): one message.
	var had = mid ? (chat.messages || []).filter(function (m) { return m && m.mid === mid; })[0] : null;
	if (had) return had;
	// Taken by the turn, but saved only when it ends: still his to get back.
	if (chat._jturn) { chat._jsaid = (chat._jsaid || []).concat([said]); journalQueue(chat); }
	var rec = pushUserRecord(chat, { role: 'user', interject: true, content: said, mid: mid || newMid(), ts: Date.now() }, true, told);
	if (rec && rec.mid) heldNote(chat, chat.app, rec.mid);		// the engine took it at its seam
	return rec;
}

/// Take back whatever was said into a turn and never got in, and queue it instead.
///
/// Called as the turn ends. The agent's queue is drained rather than read: what
/// is still in it is exactly what found no seam, and it must not be delivered
/// into some later turn by an agent that outlives this one. A turn with no tool
/// call in it has no seam, so this is not an edge case — it is the ordinary fate
/// of a correction typed into a plain prose answer.
///
/// What comes back goes in FRONT of anything already queued: it was typed first.
export function reclaimInterjections(chat, take, keep) {
	var left = [];
	if (typeof take === 'function') {
		try { left = Array.prototype.slice.call(take() || []); }
		catch (e) { left = []; }
	} else if (chat.app && typeof chat.app.take_interjections === 'function') {
		try { left = Array.prototype.slice.call(chat.app.take_interjections() || []); }
		catch (e) { left = []; }
	}
	var took = left.length;
	if (keep === false) left = [];		// said on another device, which keeps its own copy
	chat._interject = [];
	chat._interjectNote = [];
	// Drained whatever happens, but only put back where there is something to put
	// it back into: a locked app has just taken the user's content off the screen,
	// and a deleted chat has nowhere to send it.
	var back = !!left.length && !pg.locked && pg.chats.indexOf(chat) !== -1;
	if (back) {
		var said = left.map(function (w) { return { text: w }; });		// said, so no press of its own
		chat._queue = (chat._queue || []).length ? said.concat(chat._queue) : said;
	}
	if (took) diag('said back', 'chat=' + String(chat.id || '') + ' unheard=' + took
		+ (back ? ' queued=' + chat._queue.length : keep === false ? ' kept by its device' : ' dropped: nowhere to put it'));
	journalQueue(chat);
	if (pg.current === chat) renderQueue();
}

/// How much is waiting on a chat, of either kind.
///
/// Both are money about to be spent and neither has been sent, so the tile badge
/// and the updater's idea of "busy" count them together.
export function waitingOn(chat) {
	if (!chat) return 0;
	return ((chat._queue || []).length) + ((chat._interject || []).length) + ((chat._retryWait || []).length);
}

/// The container the queued bubbles live in, always the last thing in the
/// thread: what is waiting sits below what has happened.
function queueBox() {
	var box = document.getElementById('chat-queued');
	if (!box) {
		box = document.createElement('div');
		box.id = 'chat-queued';
		box.className = 'chat-queued';
		chatOutput.appendChild(box);
	} else if (box !== chatOutput.lastElementChild) {
		chatOutput.appendChild(box);
	}
	return box;
}

/// Draw everything of the current chat's that has been typed and not yet sent:
/// what is waiting on the running turn, then what is queued behind it.
///
/// Two lists in one box, because to the person who typed them they are one thing
/// -- said, not yet delivered -- and the only difference is how soon. The
/// heading over each says which, at the moment it matters; the bubbles are the
/// same dashed bubbles either way, and both can be withdrawn the same two ways.
///
/// A waiting bubble is NOT `.chat-msg-user`: that class is what the turn
/// machinery counts questions by, so a bubble wearing it would be a turn that
/// does not exist -- shifting every turn number a fold maps through.
export function renderQueue() {
	journalQueue(pg.current);		// every change to the queue on screen redraws it, so lands here
	if (!chatOutput) return;
	var waiting = (pg.current && pg.current._interject) || [];
	var q       = ((pg.current && pg.current._queue) || []).map(queuedText);
	// A retry waiting on its Diamond's own turn (`awaitDiamondIdle`) is drawn as queued words are.
	var rw      = ((pg.current && pg.current._retryWait) || []).map(function (w) { return w.text; });
	var existing = document.getElementById('chat-queued');
	if (!waiting.length && !q.length && !rw.length) {
		if (existing) existing.remove();
		updateQueueBadges();
		return;
	}
	var box = queueBox();
	box.innerHTML = '';
	if (waiting.length) waitingRows(box, t('chat.interject_help'), waiting, t('chat.interject_pending'), unwait);
	if (q.length)       waitingRows(box, askHolds() ? t('chat.queue_held') : t('chat.queue_help'), q, t('chat.queued_pending'), unqueue);
	if (rw.length)      waitingRows(box, t('chat.queue_help'), rw, t('chat.queued_pending'), function (i, toComposer) {
		endRetryWait(pg.current, i, toComposer);
	});
	if (nearBottom()) setScrollTop(chatOutput.scrollHeight);
	updateQueueBadges();
}

/// One list of not-yet-sent bubbles, under its own heading.
///
/// `take(i, toComposer)` is how a bubble is withdrawn, and it differs between
/// the two lists: one is held by the running agent, the other by the chat.
function waitingRows(box, headText, list, pendingHelp, take) {
	var head = document.createElement('div');
	head.className = 'chat-queued-head';
	head.textContent = headText;
	box.appendChild(head);
	list.forEach(function (text, i) {
		var div = document.createElement('div');
		div.className = 'chat-msg chat-msg-queued';
		div.innerHTML = '<div class="chat-msg-content"></div>';
		var body = div.querySelector('.chat-msg-content');
		body.textContent = text;                     // escaped (H5)
		body.title = pendingHelp;
		// Clicking it takes it back: the commonest thing to want from a message
		// not yet sent is to change it.
		body.addEventListener('click', function () { take(i, true); });
		var x = document.createElement('button');
		x.className = 'queue-x';
		x.textContent = '×';
		x.title = t('chat.queue_cancel');
		x.setAttribute('aria-label', t('chat.queue_cancel'));
		x.addEventListener('click', function (e) { e.stopPropagation(); take(i, false); });
		div.appendChild(x);
		box.appendChild(div);
	});
}

/// The badge a chat's tile wears while something is waiting on it, or null
/// when nothing is. `diamond-pending` is the app's existing pending-badge
/// style — the same small accented word the rail already uses for a fold
/// waiting on a Diamond, which is the same thing being said about a chat.
export function queueBadge(chat) {
	var n = waitingOn(chat);
	if (!n) return null;
	var b = document.createElement('span');
	b.className = 'diamond-pending queue-badge';
	b.textContent = tn('chat.queue_badge', n);
	b.title = tn('chat.queue_badge_help', n);
	return b;
}

/// The conversation one rail tile stands for, or null.
///
/// A chat tile's `dataset.id` IS a chat id. A DIAMOND tile's is the DIAMOND'S,
/// and the conversation that queues under it is its daimon's -- an ordinary
/// record in `chats` carrying `diamondId`, with no tile of its own. Looking the
/// second up in a map keyed by the first is the quiet failure this exists to
/// prevent: every lookup misses, `queueBadge(undefined)` is null, and the badge
/// is stripped on every pass by the very function meant to keep it current --
/// correct-looking the moment it is drawn and permanently wrong after.
///
/// # Arguments
/// * `byId` - Chats by their own id, built once by the caller.
function tileConversation(box, byId) {
	if (!box) return null;
	var id = box.dataset.id || '';
	if (!id) return null;
	if (box.classList.contains('diamond-box')) {
		// WITHOUT creating one: `daimonChat` would mint an empty session for
		// every Diamond the user has never opened, on every rail refresh.
		for (var i = 0; i < pg.chats.length; i++) if (pg.chats[i].diamondId === id) return pg.chats[i];
		return null;
	}
	return byId[id] || null;
}

/// The row one rail tile keeps its queue badge in, made if it is not there yet.
///
/// The two shapes of tile keep it in different rows and the choice is not
/// cosmetic. A chat's goes in `.tile-active-top`, beside Fold and Keep. A
/// Diamond's goes in `.session-box-meta`, beside the pending-fold badge --
/// because `app.css` keeps that row alive in Simple with
/// `:not(:has(.diamond-pending))`, and `queueBadge` returns a
/// `.diamond-pending`, so the meta row is the ONE row on a Diamond tile where
/// the badge survives the view the stylesheet says it survives. `.diamond-meter`
/// below the tags is hidden in Simple outright, and the header is the control
/// row.
///
/// A Diamond with no model chip and no pending fold has no meta row at all --
/// an empty row still costs its top margin, so `diamondBox` does not append one
/// -- hence the row is built here on demand and put where `diamondBox` puts it:
/// under the header, above the tags.
function queueBadgeSlot(box) {
	if (!box.classList.contains('diamond-box')) return box.querySelector('.tile-active-top');
	var meta = box.querySelector('.session-box-meta');
	if (meta) return meta;
	meta = document.createElement('div');
	meta.className = 'session-box-meta';
	box.insertBefore(meta, box.querySelector(':scope > .session-box-tags')
		|| box.querySelector(':scope > .diamond-meter') || null);
	return meta;
}

/// Bring every tile's queue badge up to date in place.
///
/// In place, rather than by redrawing the rail: renderSessionList rebuilds the
/// label inputs, so a queue changing under a half-typed rename would take the
/// caret out of it.
///
/// BOTH RAILS. It scanned `sessionList` alone, which is why a Diamond's tile
/// never carried the badge even after `diamondBox` learned to draw one: the
/// build would put it there and the first refresh would not know the tile
/// existed, so it froze at whatever the queue was when the rail was last
/// redrawn.
function updateQueueBadges() {
	var byId = {};
	pg.chats.forEach(function (c) { byId[c.id] = c; });
	var boxes = [];
	if (sessionList) boxes = boxes.concat(
		Array.prototype.slice.call(sessionList.querySelectorAll('.session-box')));
	if (diamondList) boxes = boxes.concat(
		Array.prototype.slice.call(diamondList.querySelectorAll('.diamond-box')));
	boxes.forEach(function (box) {
		// The old badge is found wherever it is rather than looked for in the row it
		// ought to be in, so a badge left behind by an earlier shape of tile is
		// cleared rather than duplicated.
		var was  = box.querySelector('.queue-badge');
		var host = was && was.parentElement;
		var now  = queueBadge(tileConversation(box, byId));
		if (was) was.remove();
		// The row is MADE only when there is something to put in it. Asking for the
		// slot unconditionally would build and drop a row on every Diamond tile on
		// every pass, and `renderQueue` reaches here on every keystroke.
		if (now) {
			var slot = queueBadgeSlot(box);
			if (slot) slot.appendChild(now);      // a pending chat cannot hold a queue
		} else if (host && !host.firstChild && host.classList.contains('session-box-meta')) {
			// A row that existed only to carry the badge still costs its top margin,
			// and in Simple an empty meta row is the one thing `:has(.diamond-pending)`
			// was written to avoid. Emptied, it goes.
			host.remove();
		}
	});
}

/// Put text back in the composer, after whatever is already typed there.
export function putInComposer(text) {
	if (!text) return;
	intoComposer(pg.current, text, false);
	chatInput.focus();
}

/// The one way words the app hands back reach `chat`'s composer: into the box when that chat is on
/// screen, else into its kept draft, ahead of what is there (`ahead`) or after it. Kept in the draft
/// at once, before the record that held them (a queue, a reload's give-back) is cleared: a value set
/// by code fires no 'input', so the drafts never saw it, and a reload before a keystroke lost the
/// words (QA ccp3r A MED-A).
export function intoComposer(chat, text, ahead) {
	if (!text) return;
	var k = chatDraftKey(chat);
	var join = function (had) {
		had = String(had || '');
		return !had.trim() ? text : (ahead ? text + '\n\n' + had : had + '\n\n' + text);
	};
	if (chatInput && (chat === pg.current || (!!k && chatInput.dataset.draftKey === k))) {
		chatInput.value = join(chatInput.value);
		fitComposer();
		syncSendMode();
		try { if (k && window.DaimondDrafts) DaimondDrafts.set(k, chatInput.value); } catch (e) { /* storage blocked */ }
	} else {
		var kept = '';
		try { kept = (k && window.DaimondDrafts) ? (DaimondDrafts.get(k) || '') : ''; } catch (e) { kept = ''; }
		chat._draft = join(chat._draft || kept);
		try { if (k && window.DaimondDrafts) DaimondDrafts.set(k, chat._draft); } catch (e) { /* storage blocked */ }
	}
}

/// Take a queued message out again: back to the composer to be edited, or
/// simply dropped.
function unqueue(i, toComposer) {
	if (!pg.current || !pg.current._queue) return;
	var item = pg.current._queue.splice(i, 1)[0];
	if (toComposer && item) putInComposer(item.text);
	renderQueue();
}

/// Take a message back out of the turn it was said into.
///
/// It has to leave the AGENT's queue, not merely the mirror drawn here: a row
/// removed from the picture and still delivered is worse than one never removed
/// at all. The agent may hand back nothing, which means the seam came round
/// between the click and this line — it is in the conversation now, so it is not
/// withdrawn and it is certainly not put back in the box to be sent a second time.
function unwait(i, toComposer) {
	if (!pg.current || !pg.current._interject || !pg.current._interject.length) return;
	var canDrop = !!(pg.current.app && typeof pg.current.app.drop_interjection === 'function');
	var got = null;
	if (canDrop) {
		try { got = pg.current.app.drop_interjection(i); }
		catch (e) { got = null; }
	}
	var mirrored = pg.current._interject.splice(i, 1)[0];
	(pg.current._interjectNote || []).splice(i, 1);
	if (canDrop && (got === null || got === undefined)) { renderQueue(); return; }
	if (toComposer) putInComposer(canDrop ? got : mirrored);
	renderQueue();
}

/// Send the next queued message, now the turn's lock is free.
///
/// Only after a turn that ended cleanly. A queue drained on the back of an
/// error or a Stop would spend money answering a question the user asked before
/// they knew the last one had failed -- so instead the text comes back to the
/// composer, where they can see it and decide.
export function drainQueue(chat, failed) {
	// A daimon's conversation is an ordinary record and can now hold a queue, but
	// its turn is `doSteer`'s -- see `drainSteerQueue`. Nothing routes one here
	// today; the guard costs a line and the alternative costs a wrong turn.
	if (chat.diamondId) return;
	var aborted = !!chat._aborted;
	chat._aborted = false;
	chat._stopWhy = '';
	var q = chat._queue || [];
	if (!q.length) return;
	// Only for the chat on screen. runTurn writes the question straight into the
	// thread, so a turn started for a chat the user has since left would render
	// into the conversation they are now looking at. A queue left on another chat
	// waits there, badged on its tile, and is picked up by resumeQueue the moment
	// the user goes back to it — which is why HOW the turn ended is recorded
	// rather than thrown away: the queue must still be handed back, not sent, if
	// the turn it was waiting behind failed or was stopped.
	if (pg.current !== chat) {
		chat._queueFailed = !!(failed || aborted);
		updateQueueBadges();
		return;
	}
	if (failed || aborted || pg._unloading || pg.chats.indexOf(chat) === -1) { returnQueue(chat); return; }
	chat._queueFailed = false;
	// A turn that ended on a question holds the queue under its card (D-20261009-20).
	if (askHolds()) { renderQueue(); return; }
	// A press in flight goes first; whatever it starts drains this when it ends.
	if (chat._sending) { Promise.resolve(chat._sent).then(function () { drainQueue(chat, false); }); return; }
	// One handed off is still out: the next waits for it to settle (`drainAfterHeld`), not beside it.
	if (dispatchInFlight(chat)) { updateQueueBadges(); return; }
	var next = q.shift();
	chat._qflight = next;		// on disk until the turn it becomes has its prompt row (`sendQueued`)
	renderQueue();
	// Through the election, as a send is: one handed off sends the next the same way.
	sendQueued(chat, next).then(function (r) { if (r === 'sent') drainQueue(chat, false); });
}

/// Send a message that waited in `chat`'s queue by the send's own door (UNBLOCK-1 QFOLLOW).
///
/// The queue ran it with `runTurn`, here, whatever the switch said: a follow-up typed
/// while a turn here was finishing ran here with the switch on argonaut, and the
/// election never saw it. The election goes first now, holding the composer as a press
/// does (`holdSend`), and only a turn it keeps here runs here. 'sent' when it was
/// handed off, 'here' when it runs here, 'kept' when it went back to the queue.
///
/// Elected under the runner drawn at its press (`item.drawn`), so one pressed under a runner
/// gone by now ends "not run" with Retry rather than running here.
///
/// The item stays on disk as `_qflight` until the turn it became has its prompt row: handed off
/// or ended "not run" when the election answers, journalled at a Here turn's start (`onStart`),
/// or back in the queue (QA ccp3 A R2).
async function sendQueued(chat, item) {
	var hold = holdSend(chat);
	var landed = function () { if (chat._qflight === item) { chat._qflight = null; journalQueue(chat); } };
	var release = function () { landed(); hold(); };
	var handed = false;
	var text = item.text;
	try {
		if (await maybeAutoDispatch(chat, text, '', undefined, undefined, item.drawn)) return 'sent';
		// The election's wait may have taken the person away or started a turn here.
		if (pg.current !== chat || chat._generating || recoveringHere(chat)) {
			chat._queue = [item].concat(chat._queue || []);
			landed();
			updateQueueBadges();
			renderQueue();
			return 'kept';
		}
		handed = true;
		Promise.resolve(runTurn(chat, text, { person: true, onStart: release })).then(release, release);
		return 'here';
	} finally {
		if (!handed) release();
	}
}

/// Pick up a queue left on a chat, now the user has come back to it.
///
/// The queue could not run while the chat was in the background — runTurn draws
/// into the live thread, so it would have written someone else's conversation —
/// and it is not run headlessly here either: this is the same drain, at the
/// first moment it is honest to do it. The turn it was waiting behind decides:
/// one that ended cleanly sends what was queued, and one that errored or was
/// stopped hands it back to the composer instead, exactly as it would have done
/// had the user been watching.
export function resumeQueue(chat) {
	if (!chat || pg.current !== chat) return;                 // they have moved on again
	if (!chat._queue || !chat._queue.length) return;
	if (chat._generating) return;                          // its own turn will drain it
	if ((chat.status || 'active') === 'pending') return;   // nothing has started here yet
	if (chat._queueFailed) {
		chat._queueFailed = false;
		returnQueue(chat);
		return;
	}
	drainQueue(chat, false);
}

/// Send what was typed into a daimon while it was busy, now it is not.
///
/// The daimon half of `drainQueue`, and deliberately NOT `drainQueue` itself:
/// that one ends in `runTurn`, which is a CHAT'S turn machinery. A daimon's
/// tools are pinned to its own directory, its fence is the Diamond's scope and
/// its turn records a crystal version -- the split `sendUserMessage` makes, and
/// running one record through the other side of it would undo the whole of it.
///
/// The rules are the chat's, for the chat's reasons. Only while this Diamond is
/// still the one on screen, because `doSteer` writes into the live thread. Not
/// after a turn that failed, because the queued question was asked before the
/// user knew the last one had. And on a later tick, because `doSteer` refuses to
/// re-enter while this Diamond is marked busy, and this runs as that mark comes off.
export function drainSteerQueue(rec, diamondId, failed) {
	if (!rec || !(rec._queue || []).length) return;
	var dq = function (how) { diag('queue drain', 'chat=' + String(rec.id || '') + ' queued=' + rec._queue.length + ' ' + how); };
	if (pg._unloading || !pg.currentDiamond || pg.currentDiamond.id !== diamondId) {
		// Left where it is, badged on the tile, with HOW the turn ended remembered
		// -- `resumeSteerQueue` needs it to decide send or hand back when the user
		// comes back, exactly as `resumeQueue` does for a chat.
		dq('left: its Diamond is not on screen');
		rec._queueFailed = !!failed;
		updateQueueBadges();
		return;
	}
	if (failed) { dq('handed back: the turn failed'); returnQueue(rec); return; }
	rec._queueFailed = false;
	if (askHolds()) { dq('held under the open question'); renderQueue(); return; }		// held under the open question, as a chat's is
	// One handed off is still out, or lapsed only by the clock: the next waits for it (`drainAfterHeld`), as a chat's does.
	if (dispatchInFlight(rec)) { dq('held behind a hand-off still out'); updateQueueBadges(); return; }
	dq('next to the election');
	var next = rec._queue.shift();
	journalQueue(rec);
	renderQueue();
	setTimeout(function () { steerQueued(rec, diamondId, next); }, 0);
}

/// `sendQueued` for a daimon: the election first, and the steer here only when it keeps
/// the turn here (UNBLOCK-1 QFOLLOW).
async function steerQueued(rec, diamondId, item) {
	var text = item.text;
	if (await maybeAutoDispatch(rec, text, '', undefined, undefined, item.drawn)) {
		drainSteerQueue(rec, diamondId, false);
		return;
	}
	if (!pg.currentDiamond || pg.currentDiamond.id !== diamondId || diamondBusy(diamondId)) {
		diag('queue drain', 'chat=' + String(rec.id || '') + ' kept: the election kept it here and it cannot run now');
		rec._queue = [item].concat(rec._queue || []);
		journalQueue(rec);
		updateQueueBadges();
		renderQueue();
		return;
	}
	runSteer(pg.currentDiamond, text, 0, null, { person: true, said: true });
}

/// Pick up a queue left on a Diamond, now the user has come back to it.
export function resumeSteerQueue(rec, diamondId) {
	if (!rec || !(rec._queue || []).length) return;
	if (!pg.currentDiamond || pg.currentDiamond.id !== diamondId) return;   // moved on again
	if (diamondBusy(diamondId)) return;                               // its own turn will drain it
	if (rec._queueFailed) { rec._queueFailed = false; returnQueue(rec); return; }
	drainSteerQueue(rec, diamondId, false);
}

/// Give a queue back rather than send it.
function returnQueue(chat) {
	var q = chat._queue || [];
	if (!q.length) return;
	var text = q.map(queuedText).join('\n\n');
	// Only into the composer of the chat that is actually on screen. A background
	// chat's queue stays where it is, still visible when the user returns to it,
	// rather than being pasted into a conversation it was not meant for.
	if (pg.current !== chat) { diag('queue back', 'chat=' + String(chat.id || '') + ' queued=' + q.length + ' left: not on screen'); return; }
	diag('queue back', 'chat=' + String(chat.id || '') + ' queued=' + q.length + ' into the composer');
	chat._queue = [];
	intoComposer(chat, text, true);
	renderQueue();
	toast(t('chat.queue_returned'), true);
}

/// Hold an exclusive lock for a chat's turn while `fn` runs, so two tabs cannot run — or later
/// resume — the same turn at once and bill it twice. Degrades to just running `fn` where the
/// Web Locks API is absent.
function withTurnLock(chatId, fn) {
	if (navigator.locks && navigator.locks.request) {
		return navigator.locks.request('daimond-turn-' + chatId, { mode: 'exclusive' }, fn);
	}
	return fn();
}

/// Run one turn of a chat, journalling every step so a tab that dies mid-turn loses nothing but
/// the split-second in flight. This is the shared core of both the composer and the Continue
/// button: `text` is the user's message; the rest is durability.
/// Put a row a turn wrote into its chat, tagged with its prompt's id (check_fix3 F2, check_fix5 H1).
///
/// A handed-off run's answer was the only row it tagged, so its tool, error, fold, vision, leak, files and end rows
/// were read by position, and a queued prompt that landed before the answer took them as its own turn's
