				turnP = Math.max(0, h2.p - tok0.p);
				turnC = Math.max(0, h2.c - tok0.c);
				turnCa = Math.max(0, h2.ca - tok0.ca);
				turnCost = Math.max(0, h2.usd - tok0.cost);
